result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_cvp.py", "content": "from decimal import Decimal

import pytest

from cvp import (
    breakeven_units,
    breakeven_revenue,
    breakeven_units_multi,
    margin_of_safety,
    units_for_target_profit,
    weighted_contribution_margin,
)

FIXED = Decimal("90000")
PRICE = Decimal("25")
VAR = Decimal("15")


def test_breakeven_units_exact():
    assert breakeven_units(FIXED, PRICE, VAR) == Decimal("9000")


def test_breakeven_revenue_exact():
    assert breakeven_revenue(FIXED, PRICE, VAR) == Decimal("225000")


def test_breakeven_nonpositive_cm_raises():
    with pytest.raises(ValueError):
        breakeven_units(100, Decimal("10"), Decimal("10"))  # zero CM
    with pytest.raises(ValueError):
        breakeven_units(100, Decimal("5"), Decimal("10"))  # negative CM


def test_units_for_target_profit():
    assert units_for_target_profit(FIXED, Decimal("30000"), PRICE, VAR) \
        == Decimal("12000")


def test_margin_of_safety():
    mos = margin_of_safety(Decimal("12000"), FIXED, PRICE, VAR)
    assert mos == Decimal("0.25")


def test_weighted_cm():
    mix = {
        "A": (30, 18, Decimal("0.6")),
        "B": (50, 26, Decimal("0.4")),
    }
    assert weighted_contribution_margin(mix) == Decimal("16.8")


def test_multiproduct_breakeven_split():
    mix = {
        "A": (30, 18, Decimal("0.6")),
        "B": (50, 26, Decimal("0.4")),
    }
    total, split = breakeven_units_multi(Decimal("84000"), mix)
    assert total == Decimal("5000")
    assert split["A"] == Decimal("3000")
    assert split["B"] == Decimal("2000")


def test_mix_fractions_must_sum_to_one():
    bad = {"A": (30, 18, Decimal("0.5")), "B": (50, 26, Decimal("0.4"))}
    with pytest.raises(ValueError):
        breakeven_units_multi(84000, bad)


def test_float_inputs_accepted_exactly():
    # Floats are coerced via str, so results stay exact.
    assert breakeven_units(90000, 25.0, 15.0) == Decimal("9000")
